<template><view class="account-page"><view v-if="loading" class="account-state">正在加载…</view><view v-else-if="loadError" class="account-state"><text>{{ loadError }}</text><button class="secondary" @click="load">重试</button></view><template v-else><view class="account-card"><view class="account-row"><text class="account-label">收货人</text><input v-model="recipient" class="account-input" placeholder="请输入收货人" :maxlength="30" :disabled="saving" /></view><view class="account-row"><text class="account-label">手机号</text><input v-model="phone" class="account-input" type="number" placeholder="请输入手机号" :maxlength="11" :disabled="saving" /></view></view><view class="account-card"><view class="account-row"><text class="account-label">所在地区</text><view class="address-region"><RegionPicker plain :codes="regionCodes" :label="regionNames.join('')" @change="regionChange" /></view></view><view class="account-row address-line"><text class="account-label">详细地址</text><textarea v-model="detail" class="account-textarea" placeholder="街道、门牌号等" :maxlength="200" auto-height :disabled="saving" /></view></view><view class="account-card"><view class="account-row"><view class="default-description"><text>设置默认地址</text><view class="account-caption">每次下单都会默认使用该地址</view></view><switch :checked="isDefault" :disabled="saving" color="#00adff" @change="isDefault = $event.detail.value" /></view></view><text v-if="error" class="account-error">{{ error }}</text><view class="account-bottom"><button class="primary" :disabled="saving" @click="save">{{ saving ? '保存中…' : '保存' }}</button></view></template></view></template>
<script setup>
import { ref } from 'vue'
import { onLoad, onUnload } from '@dcloudio/uni-app'
import { useAuth } from '../../composables/useAuth'
import { getAddress, saveAddress } from '../../services/profile'
import RegionPicker from '../../components/RegionPicker.vue'
useAuth()
const recipient = ref(''), phone = ref(''), detail = ref(''), regionCodes = ref([]), regionNames = ref([]), isDefault = ref(false), loading = ref(true), loadError = ref(''), error = ref(''), saving = ref(false)
let id = '', version, epoch = 0
async function load() { const current = ++epoch; loading.value = true; loadError.value = ''; try { if(id) { const {address} = await getAddress(id); if(current !== epoch) return; recipient.value = address.recipient; phone.value = address.phone; detail.value = address.detail; regionCodes.value = address.regionCodes; regionNames.value = address.regionNames; isDefault.value = address.isDefault; version = address.version } } catch(reason) { if(current === epoch) loadError.value = reason.message || '地址加载失败' } finally { if(current === epoch) loading.value = false } }
function regionChange(value) { if(saving.value) return; regionCodes.value = value.codes; regionNames.value = value.names }
async function save() { if(saving.value) return; const current = epoch; saving.value = true; error.value = ''; try { await saveAddress(id,{recipient:recipient.value,phone:phone.value,detail:detail.value,regionCodes:regionCodes.value,regionNames:regionNames.value,isDefault:isDefault.value,version}); if(current === epoch) { uni.showToast({title:'已保存',icon:'success'}); if(getCurrentPages().length>1) uni.navigateBack(); else uni.redirectTo({url:'/pages/address/list'}) } } catch(reason) { if(current === epoch) error.value = reason.message || '保存失败' } finally { if(current === epoch) saving.value = false } }
onLoad(options=>{id=options.id||'';uni.setNavigationBarTitle({title:id?'编辑地址':'添加地址'});load()});onUnload(()=>{++epoch})
</script>
<style>@import '../../styles/account.css';</style>
<style scoped>.address-region{flex:1;min-width:0;--auth-input-height:60rpx}.address-line{align-items:flex-start}.default-description{flex:1;min-width:0;font-size:29rpx}.account-caption{font-size:23rpx}</style>
